package net.civeira.phylax.features.access.tenantconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class WebauthnRpNameVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property webauthn rp name of tenant config ")
  void test_webauthn_rp_name_v_o_builder() {
    Assertions.assertFalse(WebauthnRpNameVO.nullValue().getWebauthnRpName().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(WebauthnRpNameVO.tryFrom(null).getWebauthnRpName().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", WebauthnRpNameVO.from("one").getWebauthnRpName().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> WebauthnRpNameVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", WebauthnRpNameVO.from("one").toString());
  }
}
